  if(!CATEGORIES.includes(category))category='Strategic';
  let r=id?db.records.find(x=>x.id===id):db.records.find(x=>x.id===currentEdit&&canEdit(user,x))||db.records.find(x=>canEdit(user,x));
  if(!r){createRecord();return;}if(!canEdit(user,r))return forbidden();currentEdit=r.id;
  const latestReturn=[...r.history].reverse().find(h=>h.action==='Returned for correction');
  shell(heading(r.status==='Returned'?'Correct your IPCR':'Create / edit IPCR',`${esc(periodName(r.period))} · ${esc(r.id)}`,badge(r.status))+`${latestReturn&&r.status==='Returned'?`<div class="notice error"><strong>Returned by ${esc(latestReturn.actor)}</strong><br>${esc(latestReturn.comment)}<br>Resubmission restarts at the Department Head.</div>`:''}
  <div class="ipcr-editor stack"><section class="panel"><div class="panel-head"><h2>Individual Performance Commitment and Review (IPCR)</h2><span id="save-status" class="small">All changes saved</span></div><div class="panel-body"><div class="form-grid">${field('Employee name','record-name',r.name,'text','data-record="name" required')}${field('Position','record-position',r.position,'text','data-record="position" required')}${field('Unit / office','record-unit',r.unit,'text','readonly')}${field('Department','record-department',r.department,'text','readonly')}${selectField('Evaluation period','record-period',db.periods.filter(p=>user.periodIds?.includes(p.id)||p.id===r.period),r.period)}${field('Employee type','record-type',r.type,'text','readonly')}<div class="field full"><label for="record-commitment">Commitment statement</label><p class="small muted">I, the employee named above, of the indicated unit, Mariano Marcos State University, Batac City, Ilocos Norte:</p><textarea class="form-control" id="record-commitment" data-record="commitment">${esc(r.commitment)}</textarea><p class="small muted" style="margin-top:8px">For the evaluation period selected above.</p></div></div><div class="ratee-editor"><div><strong id="ratee-display">${esc(r.name)}</strong><span>Ratee</span></div>${field('Ratee date','record-rateeDate',r.rateeDate||'','date','data-record="rateeDate"')}</div>${formalReviewFields(r)}<p class="small muted" style="margin:10px 0 0">Review and approval names/dates follow the current submission’s workflow. Pending fields are not signatures.</p></div></section>
  ${ratingLegend()}<section class="panel"><div class="panel-head"><div><h2>Performance commitments & accomplishments</h2><p class="small">Choose a section; entries in the other sections stay saved.</p></div></div><nav class="step-tabs" aria-label="IPCR function sections">${CATEGORIES.map((c,i)=>`<a class="${category===c?'active':''}" href="#edit/${c}/${r.id}"><span class="step-number">${i+1}</span>${c} Functions</a>`).join('')}</nav><div id="editor-errors" role="alert"></div><datalist id="ipcr-programs">${referencePrograms().map(p=>`<option value="${esc(p.name)}">`).join('')}<option value="Functions of University Designations"></datalist><div class="table-wrap ipcr-edit-scroll"><table class="ipcr-table editable-table">${ipcrTableHeader()}<tbody id="function-rows">${ipcrSectionRows(r,category,true)}</tbody></table></div><div class="ipcr-table-actions"><button class="btn btn-light" id="add-row">${icon('plus-lg')} Add function</button>${r.type==='Teaching'?'<button class="btn btn-light" id="add-reference">Add functions from sample</button>':''}<span class="small muted">Q / E / T: 1–5 · A is calculated automatically</span></div></section>
  <section class="panel panel-body" id="rating-summary">${renderIPCRSummary(r,true)}</section><section class="panel"><div class="panel-head"><h2>Comments / Recommendations for development plan</h2></div><div class="panel-body"><label class="sr-only" for="record-development">Comments / recommendations for a development plan</label><textarea id="record-development" data-record="development" class="form-control" placeholder="Development needs, recommended action, and support required…">${esc(r.development)}</textarea>${ipcrFooter(r,true)}</div></section><div class="editor-actions"><button class="btn btn-light" id="save-draft">${icon('floppy')} Save draft</button><div class="actions">${link('Preview full form','detail/'+r.id,'btn btn-light','eye')}<button class="btn btn-primary" id="submit-ipcr">${r.status==='Returned'?'Resubmit IPCR':'Submit IPCR'} ${icon('send')}</button></div></div></div>`,category+' Functions');
  bindIPCREditor(r,category);
